query:
UPDATE course_lessons SET content = REPLACE(
  REPLACE(content,
    '*   **Parameter `d320` [Control Temp]:** Displays the temperature of the control board.',
    '*   **Parameter `b024` [Drive Temp]:** Displays the heatsink temperature in °C. *(Note: d320/d321 are PowerFlex 750 series parameters — the PF525 uses b024.)*'
  ),
  '*   **Parameter `d321` [Drive Temp]:** Displays the temperature of the power section (heatsink).',
  '*   **Parameter `b025` [Drive Status]:** Shows drive status bits including thermal warnings.'
) WHERE id = 30027;

